        if n % i == 0:
            return False
    return True

def check_good(x, y, z):
    try:
        # Need to handle negative bases and exponents carefully
        # y^x * z^y * x^z = p
        # x, y, z are integers

        # To avoid float precision issues with negative exponents, 
        # we use fractions or check if the result is an integer.
        import fractions

        res = (fractions.Fraction(y)**x) * (fractions.Fraction(z)**y) * (fractions.Fraction(x)**z)
        if res.denominator == 1:
            val = res.numerator
            if is_prime(val):
                return True
    except (ZeroDivisionError, OverflowError, ValueError):
        pass
    return False

